class Bowl:
    def __init__(self, n):
        self.n = n

    def __str__(self):
        return "装了 " + str(self.n) + " 条小鱼干"

    def __add__(self, other):
        return Bowl(self.n + other.n)


n = int(input())
total = Bowl(int(input()))
for _ in range(n - 1):
    total = total + Bowl(int(input()))
print(total)
